'use strict';

/* ─── About this file ─────────────────────────────────────────────────────────
 * Tests the real Discord message handler (src/commands.js) with fake Discord
 * objects: the channel gate, staff never being scam-actioned, and Q&A learning
 * storing only answers to real questions. Runs in a sandbox copy so the scam
 * blocker toggle and learned Q&A never touch real data.
 * ─────────────────────────────────────────────────────────────────────────── */

// ----- Contents (generated by `npm run index` — do not edit) -----
// L25   Fixture
// L28     BOT
// L32     setup()
// L71       done()
// L80     msg()
// L100  Channel gate
// L131  Scam blocker
// L609  Q&A learning
// ----- end of contents -----

const test   = require('node:test');
const assert = require('node:assert');
const { makeSandbox } = require('./helpers');

// ─── Fixture ──────────────────────────────────────────────────────────────────

// Fake IDs: the bot, an answer channel (also #general), a non-answer channel, and the staff role.
const BOT = 'bot1', ANSWER_CH = 'general', OTHER_CH = 'other', STAFF_ROLE = 'staffRole';

// Builds the handler in a sandbox; `intent` decides what the fake classifier returns, and `tweets`
// (status ID → tweet, or null for "can't be read") stands in for FxTwitter.
function setup({ intent = 'help-seeking', scamBlocker = true, tweets = {}, bareLinkIsSite = false, breakLinkReview = false } = {}) {
    const box = makeSandbox(['src/commands.js', 'src/toggles.js', 'src/state.js', 'src/utils.js', 'src/tweet-check.js'], {
        'data/toggles.json': JSON.stringify({ discord: true, telegram: true, 'scam-blocker': scamBlocker }),
    });
    const state = require(box.path('src/state.js'));
    const utils = require(box.path('src/utils.js'));
    if (breakLinkReview) utils.stripOfficialLinks = () => { throw new Error('link review broken'); };
    const { registerMessageHandler } = require(box.path('src/commands.js'));
    const seen = { answered: [], learned: [], infractions: 0, deleted: 0, records: [], forwarded: [], removedFromAi: [], bareLinkChecks: [], bareLinkInputs: [] };
    const handlers = {};
    const client = { on: (ev, fn) => { (handlers[ev] ??= []).push(fn); }, user: { id: BOT }, channels: { cache: new Map(), fetch: async (id) => (id === '1502041137119105054' ? { send: async (m) => { seen.forwarded.push(m); return { delete: async () => seen.removedFromAi.push(m) }; } } : null) } };
    registerMessageHandler(client, state, {
        BOT_ANSWER_CHANNEL_IDS: [ANSWER_CH], STAFF_ROLE_IDS: [STAFF_ROLE], GENERAL_CHANNEL_ID: ANSWER_CH, SUPPORT_CHANNEL_ID: 'support',
        SUPPORT_TICKET_CATEGORY_IDS: new Set(['ticketCat']), COLLAB_CATEGORY_IDS: new Set(),
    }, {
        claude: { answerQuestion: async (a) => seen.answered.push(a.question), identifyRelevantSources: () => [] },
        intent: {
            classifyMessageIntent: async () => intent, logMessageIntent: () => {}, logIntentClassification: () => {},
            RESPOND_INTENTS: new Set(['help-seeking', 'troubleshooting', 'onboarding', 'factual-question']),
            logToTicketFile: () => {}, logToCollabFile: () => {},
            hasSoftScamSignal: (t) => /\b(inbox|dm)\b/i.test(t),
            detectBareLinkLLM: async (text, links, seconds, above) => { seen.bareLinkChecks.push(links); seen.bareLinkInputs.push({ text, above }); return bareLinkIsSite; },
        },
        kbSync: {},
        utils: { ...utils, saveQAPair: (ch, q, a) => seen.learned.push({ q, a }), appendToMonthlyWeeklyFile: () => {} },
        buildIndex: async () => {}, searchKB: async () => ({ context: '', sources: [] }), htmlToMarkdown: async () => '',
        EmbedBuilder: class {},
        scamTracker: {
            recordInfraction: (id, rec) => { seen.records.push(rec); return ++seen.infractions; },
            updateInfractionActions: () => {},
            updateInfractionEvidence: (id, n, patch) => Object.assign(seen.records[n - 1].evidence, patch),
            getAllRecords: () => ({}),
        },
        tweetChecker: require(box.path('src/tweet-check.js')).createTweetChecker({
            fetchTweet: async (id) => (tweets[id] ?? { error: 'NOT_FOUND' }),
            retryDelaysMs: [],
        }),
    });
    // Clears pending auto-answer timers (or the test process would wait for them) and deletes the sandbox.
    const done = () => { for (const [, v] of state.pendingQuestions) clearTimeout(v.timer); box.cleanup(); };
    return {
        handler: (m) => Promise.all(handlers.messageCreate.map(f => f(m))),
        deleted: (m) => Promise.all(handlers.messageDelete.map(f => f(m))),
        state, seen, done,
    };
}

// A fake Discord message. `replyTo` is { id, authorId, ping }; `staff` gives the sender the staff role.
function msg(channelId, content, { replyTo = null, staff = false, mentionBot = false, id = `m${Math.random()}` } = {}) {
    const ref = replyTo && { id: replyTo.id, author: { id: replyTo.authorId, bot: replyTo.authorId === BOT }, content: 'earlier answer', reference: null };
    const roles = new Map(staff ? [[STAFF_ROLE, {}]] : []);
    return {
        id, content: mentionBot ? `<@${BOT}> ${content}` : content, channelId,
        guild: { members: { fetch: async () => null } },
        author: { id: staff ? 'staff1' : 'user1', bot: false, username: 'u', tag: 'u#1' },
        member: { roles: { cache: roles }, displayName: 'u', timeout: async () => {} },
        mentions: { users: new Map(mentionBot ? [[BOT, {}]] : []), repliedUser: replyTo?.ping ? { id: replyTo.authorId } : null },
        reference: replyTo ? { messageId: replyTo.id } : null, attachments: new Map(),
        channel: { parentId: null, name: channelId, messages: { cache: new Map(), fetch: async () => ref } },
        reply: async () => ({ id: 'r1' }), delete: async function () { this.deleted = true; },
        // A real forward fails once the original is gone.
        forward: async function (ch) {
            if (this.deleted) throw new Error('Unknown Message');
            return ch.send({ realForwardOf: this.id, content: this.content });
        },
    };
}

// ─── Channel gate ─────────────────────────────────────────────────────────────

test('channel gate: replies to the bot work in any channel; unprompted answers only in answer channels', async () => {
    const t = setup();
    try {
        await t.handler(msg(OTHER_CH, 'how do I stake river'));
        assert.strictEqual(t.seen.answered.length, 0, 'plain message outside answer channels is ignored');
        await t.handler(msg(OTHER_CH, 'and what about unlocks', { replyTo: { id: 'b1', authorId: BOT, ping: true } }));
        assert.strictEqual(t.seen.answered.length, 1, 'reply to the bot (pinged) is answered');
        await t.handler(msg(OTHER_CH, 'and what about unlocks', { replyTo: { id: 'b2', authorId: BOT, ping: false } }));
        assert.strictEqual(t.seen.answered.length, 2, 'reply to the bot (no ping) is answered');
        await t.handler(msg(OTHER_CH, 'how do I stake river', { replyTo: { id: 'p1', authorId: 'someone', ping: true } }));
        assert.strictEqual(t.seen.answered.length, 2, 'reply to a person outside answer channels is ignored');
        await t.handler(msg(OTHER_CH, 'thanks', { replyTo: { id: 'b3', authorId: BOT, ping: true } }));
        assert.strictEqual(t.state.pendingQuestions.size, 0, 'one-word reply outside answer channels is not queued');
        await t.handler(msg(ANSWER_CH, 'how do I stake river'));
        assert.strictEqual(t.state.pendingQuestions.size, 1, 'question in an answer channel is queued for auto-answer');
    } finally { t.done(); }
});

test('a question deleted while waiting for its auto-answer is dropped', async () => {
    const t = setup();
    try {
        await t.handler(msg(ANSWER_CH, 'how do I stake river', { id: 'ask1' }));
        assert.strictEqual(t.state.pendingQuestions.size, 1);
        t.deleted({ id: 'ask1' });
        assert.strictEqual(t.state.pendingQuestions.size, 0, 'pending answer cancelled');
        assert.strictEqual(t.state.pendingMsgIndex.size, 0);
    } finally { t.done(); }
});

// ─── Scam blocker ─────────────────────────────────────────────────────────────

// The fixture hands the handler all of utils; bot.js hands over a written-out list. A name the handler
// expects that bot.js leaves out is undefined only in the real bot, where it crashed the scam blocker
// before it could delete anything (2026-11-03).
test('bot.js passes the message handler every helper it expects', () => {
    const fs = require('fs');
    const path = require('path');
    const read = (f) => fs.readFileSync(path.join(__dirname, '..', f), 'utf8');
    const group = (text, name) => (text.match(new RegExp(`\\b${name}:\\s*\\{([^}]*)\\}`))?.[1] ?? '').split(',').map(s => s.trim()).filter(Boolean);
    const handler = read('src/commands.js');
    const wiring = read('bot.js').slice(read('bot.js').indexOf('registerMessageHandler(discordClient'));
    for (const name of ['kbSync', 'utils']) {
        const expected = group(handler, name);
        assert.ok(expected.length > 0, `found the ${name} list in commands.js`);
        const passed = group(wiring, name);
        assert.deepStrictEqual(expected.filter(n => !passed.includes(n)), [], `${name} helpers missing from bot.js`);
    }
});

test('helper offer: "through direct message" counts, ordinary mentions of DMs do not', () => {
    const { looksLikeHelperOffer } = require('../src/utils');
    assert.ok(looksLikeHelperOffer('could you please elaborate more on the issue you’re encountering through direct message'));
    assert.ok(looksLikeHelperOffer('explain it via dm please'));
    assert.ok(!looksLikeHelperOffer('someone tried to scam me in my direct messages yesterday'));
    assert.ok(!looksLikeHelperOffer('I got a weird direct message, is it fake?'));
});

test('staff-like name: never acted on alone; name plus a DM offer is', async () => {
    const t = setup({ intent: 'community-discussion' });
    try {
        t.state.staffNameCache.set('mrfish', 'MrFish | River');
        const nameOnly = msg(ANSWER_CH, 'hello everyone');
        nameOnly.member.displayName = 'MrFish River';
        await t.handler(nameOnly);
        assert.strictEqual(nameOnly.deleted, undefined, 'name alone: left up');
        assert.strictEqual(t.seen.infractions, 0);
        const offer = msg(ANSWER_CH, 'please explain the issue through direct message');
        offer.member.displayName = 'MrFish River';
        await t.handler(offer);
        assert.strictEqual(offer.deleted, true, 'name + DM offer: deleted');
        assert.match(t.seen.records[0].reason, /name-spoof/);
    } finally { t.done(); }
});

test('a failed AutoMod miss report does not stop the delete and timeout', async () => {
    const t = setup({ intent: 'scam-content', breakLinkReview: true });
    try {
        const m = msg(ANSWER_CH, 'dm me for help', { mentionBot: true });
        let timedOut = false;
        m.member.timeout = async () => { timedOut = true; };
        await t.handler(m);
        assert.strictEqual(t.seen.infractions, 1, 'infraction recorded');
        assert.strictEqual(m.deleted, true, 'message still deleted');
        assert.strictEqual(timedOut, true, 'member still timed out');
    } finally { t.done(); }
});

test('scam blocker never acts on staff, but does act on non-staff', async () => {
    const t = setup({ intent: 'scam-content' });
    try {
        const staffMsg = msg(OTHER_CH, 'is t.me/someone legit?', { staff: true, mentionBot: true });
        await t.handler(staffMsg);
        assert.strictEqual(staffMsg.deleted, undefined, 'staff message not deleted');
        assert.strictEqual(t.seen.infractions, 0, 'no infraction recorded for staff');
        const userMsg = msg(OTHER_CH, 'dm me for help', { mentionBot: true });
        await t.handler(userMsg);
        assert.strictEqual(userMsg.deleted, true, 'non-staff scam message deleted');
        assert.strictEqual(t.seen.infractions, 1, 'infraction recorded for non-staff');
    } finally { t.done(); }
});

test('scam blocker keeps evidence: the replied-to message, attachments and link previews', async () => {
    const t = setup({ intent: 'scam-content' });
    try {
        const m = msg(ANSWER_CH, 'check dm', { replyTo: { id: 'q1', authorId: 'victim', ping: true } });
        m.attachments = new Map([['a1', { name: 'shot.png', contentType: 'image/png' }]]);
        m.embeds = [{ url: 'https://x.com/a/status/1', author: { name: 'Support Desk' }, description: 'Create a ticket https://discord.gg/x' }];
        await t.handler(m);
        await new Promise(r => setImmediate(r));   // the replied-to message is fetched in the background
        assert.strictEqual(t.seen.forwarded.length, 0, 'an invite only in the link preview is not an AutoMod miss');
        const ev = t.seen.records[0].evidence;
        assert.deepStrictEqual(ev.attachments, [{ name: 'shot.png', type: 'image/png' }]);
        assert.strictEqual(ev.previews[0].author, 'Support Desk');
        assert.match(ev.previews[0].text, /discord\.gg/);
        assert.strictEqual(ev.repliedToId, 'q1');
        assert.strictEqual(ev.repliedTo.authorId, 'victim', 'who the scammer was targeting');
    } finally { t.done(); }
});

test('#ai report: links in the message text, including bare ones, but not X/Twitter or official links', async () => {
    const t = setup({
        intent: 'scam-content',
        tweets: { '111': { name: 'CREATE A TICKET', handle: 'createticket_x', text: 'Create a ticket 👉 https://discord.gg/abc' } },
    });
    const reported = async (text) => {
        t.seen.forwarded.length = 0;
        const m = msg(ANSWER_CH, text);
        await t.handler(m);
        assert.strictEqual(m.deleted, true, `caught: ${text}`);
        await new Promise(r => setImmediate(r));   // the report is sent in the background
        return t.seen.forwarded.map(f => f.content);
    };
    try {
        const sample = 'Please use the designated hub for your inquiry. :point_down:\n\n:point_right: ::discord.co/invite/hQ82RUCQD\n\n\nNote: Remove the :: on the invite and paste the rest into your browser.';
        const [header, original] = await reported(sample);
        assert.match(header, /AutoMod miss/);
        assert.match(header, /link\(s\): discord\.co\/invite\/hQ82RUCQD\n/, 'the disguised invite is named');
        assert.strictEqual(original, sample, 'followed by the original message, exactly as written');
        assert.ok(t.seen.forwarded[1].realForwardOf, 'as a real Discord forward, sent before the message was deleted');
        assert.deepStrictEqual(t.seen.forwarded[0].allowedMentions, { parse: [] }, 'nobody is pinged');

        assert.match((await reported('join discord . gg/abc now'))[0], /link\(s\): discord \. gg\/abc/, 'spaces around the dot');
        assert.match((await reported('join discord[.]gg/abc now'))[0], /link\(s\): discord\[\.\]gg\/abc/, 'bracketed dot');
        assert.match((await reported('join discord dot gg/abc now'))[0], /link\(s\): discord dot gg\/abc/, 'the word dot');
        assert.match((await reported('open https://disc0rd.gg/abc'))[0], /link\(s\): disc0rd\.gg\/abc/, 'lookalike spelling');
        assert.match((await reported('open https://discord-verify.xyz/abc'))[0], /link\(s\): discord-verify\.xyz\/abc/, 'lookalike domain');
        assert.match((await reported('open https://discord.gg/abc'))[0], /link\(s\): discord\.gg\/abc/, 'a plain invite');
        assert.match((await reported('go here https://x.com/a/status/9 or join dsc.gg/abc'))[0], /link\(s\): dsc\.gg\/abc\n/, 'beside an X link: still reported');

        const check = /^\*\*Link in a caught message — please check\*\*/;
        for (const [text, link] of [
            ['Check yours 👇\nghosts-wallet.xyz/apps', 'ghosts-wallet.xyz/apps'],
            ['who has more than me?\nghostwallet.pages.dev', 'ghostwallet.pages.dev'],
            ['Have you check ✅\n\n a2zphone5.online\n\n for get phone token airdrop', 'a2zphone5.online'],
            ['ask them at t.me/fakehelp now', 't.me/fakehelp'],
            ['claim here https://ghost-wallet.xyz/claim', 'https://ghost-wallet.xyz/claim'],
        ]) {
            const [head, original] = await reported(text);
            assert.match(head, check, `reported: ${text}`);
            assert.ok(head.includes(`link(s): ${link}\n`), `names ${link}: ${head}`);
            assert.strictEqual(original, text, 'followed by the message as written');
        }
        assert.deepStrictEqual(await reported('A.dd me up for a gu1de regarding this known issue'), [], 'altered word, not a link');
        assert.deepStrictEqual(await reported('Visit the live sup-port desk using the li.nk on my pro-file'), [], 'altered word, not a link');
        assert.deepStrictEqual(await reported('reach out to the team for assistance.re currently ongoing'), [], 'altered word, not a link');
        assert.deepStrictEqual(await reported('dm me or see Riverai.inc and https://docs.riverai.inc/x'), [], "River's own links");
        assert.deepStrictEqual(await reported('https://x.com/createticket_x/status/111'), [], 'invite only inside the tweet');
        assert.deepStrictEqual(await reported('ask here https://twitter.com/createticket_x/status/111 thanks'), [], 'twitter.com link');
        assert.deepStrictEqual(await reported('see https://discord.com/channels/1/2 for the fix'), [], "a message link is not an invite");
        assert.deepStrictEqual(await reported('you were contacted on discord, check your dm'), [], 'the word Discord alone');
    } finally { t.done(); }
});

