test('Q&A learning: staff replies are learned only for real questions', async () => {
    const chat = setup({ intent: 'general-greeting' });
    try {
        await chat.handler(msg(ANSWER_CH, 'good morning everyone', { id: 'q1' }));
        await chat.handler(msg(ANSWER_CH, 'morning!', { staff: true, replyTo: { id: 'q1', authorId: 'user1' } }));
        assert.strictEqual(chat.seen.learned.length, 0, 'reply to a greeting is not learned');
    } finally { chat.done(); }

    const question = setup({ intent: 'help-seeking' });
    try {
        await question.handler(msg(ANSWER_CH, 'how do I claim my S6 airdrop?', { id: 'q2' }));
        await question.handler(msg(ANSWER_CH, 'connect your wallet on the airdrop page', { staff: true, replyTo: { id: 'q2', authorId: 'user1' } }));
        assert.strictEqual(question.seen.learned.length, 1, 'reply to a question is learned');
        assert.match(question.seen.learned[0].q, /claim my S6 airdrop/);
    } finally { question.done(); }
});
